class Solution {
public:
    int medianOfLevel(TreeNode* root, int level) {
        queue<TreeNode*> q; q.push(root);
        int d = 0;
        while (!q.empty() && d < level) {
            int sz = q.size();
            while (sz--) {
                TreeNode* node = q.front(); q.pop();
                if (node->left) q.push(node->left);
                if (node->right) q.push(node->right);
            }
            d++;
        }
        if (q.empty() || d != level) return -1;
        vector<int> vals;
        while (!q.empty()) { vals.push_back(q.front()->val); q.pop(); }
        sort(vals.begin(), vals.end());
        return vals[vals.size() / 2];
    }
};

