import java.util.*;
class Solution {
    public int medianOfLevel(TreeNode root, int level) {
        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);
        int d = 0;
        while (!q.isEmpty() && d < level) {
            int sz = q.size();
            while (sz-- > 0) {
                TreeNode node = q.poll();
                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            }
            d++;
        }
        if (q.isEmpty() || d != level) return -1;
        List<Integer> vals = new ArrayList<>();
        for (TreeNode node : q) vals.add(node.val);
        Collections.sort(vals);
        return vals.get(vals.size() / 2);
    }
}

