var medianOfLevel = function(root, level) {
    let q = [root], d = 0;
    while (q.length && d < level) {
        const next = [];
        for (const node of q) {
            if (node.left) next.push(node.left);
            if (node.right) next.push(node.right);
        }
        q = next;
        d++;
    }
    if (!q.length || d !== level) return -1;
    const vals = q.map(n => n.val).sort((a, b) => a - b);
    return vals[Math.floor(vals.length / 2)];
};

