    def medianOfLevel(self, root: Optional[TreeNode], level: int) -> int:
        buckets = {}
        def dfs(node, d):
            if not node: return
            buckets.setdefault(d, []).append(node.val)
            dfs(node.left, d + 1)
            dfs(node.right, d + 1)
        dfs(root, 0)
        if level not in buckets:
            return -1
        vals = sorted(buckets[level])
        return vals[len(vals) // 2]

