class Solution {
public:
    void dfs(TreeNode* node, int d, unordered_map<int, vector<int>>& b) {
        if (!node) return;
        b[d].push_back(node->val);
        dfs(node->left, d + 1, b);
        dfs(node->right, d + 1, b);
    }
    int medianOfLevel(TreeNode* root, int level) {
        unordered_map<int, vector<int>> b;
        dfs(root, 0, b);
        auto it = b.find(level);
        if (it == b.end()) return -1;
        sort(it->second.begin(), it->second.end());
        return it->second[it->second.size() / 2];
    }
};

