import java.util.*;
class Solution {
    private void dfs(TreeNode node, int d, Map<Integer, List<Integer>> b) {
        if (node == null) return;
        b.computeIfAbsent(d, k -> new ArrayList<>()).add(node.val);
        dfs(node.left, d + 1, b);
        dfs(node.right, d + 1, b);
    }
    public int medianOfLevel(TreeNode root, int level) {
        Map<Integer, List<Integer>> b = new HashMap<>();
        dfs(root, 0, b);
        List<Integer> vals = b.get(level);
        if (vals == null) return -1;
        Collections.sort(vals);
        return vals.get(vals.size() / 2);
    }
}

